import React, { useEffect, useState } from "react";
import { Filters } from "./components/Filters";
import { DataTable } from "./components/DataTable";

export default function App() {
  const [data, setData] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [ville, setVille] = useState("");

  useEffect(() => {
    fetch("http://localhost:5000/api/data")
      .then((res) => res.json())
      .then((result) => {
        setData(result);
        setFiltered(result);
      });
  }, []);

  useEffect(() => {
    if (ville === "") {
      setFiltered(data);
      return;
    }

    fetch(`http://localhost:5000/api/data/${ville}`)
      .then((res) => res.json())
      .then((res) => setFiltered(res));
  }, [ville]);

  const handleScrape = () => {
    fetch("http://localhost:5000/api/scrape", { method: "POST" })
      .then((res) => res.json())
      .then((res) => alert(res.message))
      .catch((err) => console.error(err));
  };

  return (
    <div className="p-6 font-sans">
      <h1 className="text-2xl font-bold mb-4">SmartScraper - Données OpenData</h1>
      <button onClick={handleScrape} className="mb-4 px-4 py-2 bg-blue-600 text-white rounded">
        Re-scraper les données
      </button>
      <Filters setVille={setVille} />
      <DataTable data={filtered} />
    </div>
  );
}
